def collect_active_users(users, cutoff):
    active_users = []

    for user in users:
        if not user.is_online or user.last_seen_at <= cutoff:
            continue

        active_users.append(user.name)

    return active_users

def clamp(value, minimum, maximum):
    if value < minimum:
        return minimum

    if value > maximum:
        return maximum

    return value

def build_summary(project):
    summary = f"{project.name}:{project.branch}"
    summary = summary.lower().replace(" ", "-")

    if not summary:
        raise RuntimeError("empty summary")

    return summary

def top_scores(entries):
    ranked = sorted(entries, key=lambda entry: entry["score"], reverse=True)

    return [
        {"rank": index + 1, "name": entry["name"], "score": entry["score"]}
        for index, entry in enumerate(ranked[:5])
    ]

def group_posts_by_tag(posts):
    grouped = {}

    for post in posts:
        for tag in post.tags:
            grouped.setdefault(tag, []).append(post.slug)

    return grouped

from dataclasses import dataclass

@dataclass(frozen=True)
class Score:
    name: str
    value: int
    accuracy: float

    @property
    def is_perfect(self) -> bool:
        return self.accuracy >= 99.5

from contextlib import contextmanager

@contextmanager
def timed(label):
    import time
    start = time.perf_counter()
    try:
        yield
    finally:
        elapsed = time.perf_counter() - start
        print(f"{label}: {elapsed:.3f}s")

def chunked(iterable, size):
    if size <= 0:
        raise ValueError("size must be positive")

    batch = []
    for item in iterable:
        batch.append(item)
        if len(batch) == size:
            yield batch
            batch = []

    if batch:
        yield batch

def index_by(items, key):
    return {key(item): item for item in items}


